// Get the requested time from Information Extractor
const requestedTime = $('Information Extractor').first().json.output.requested_time;

// Get calendar events from previous node
const calendarEvents = $input.all();

// Business hours configuration
const BUSINESS_START = 9; // 9 AM
const BUSINESS_END = 17;   // 5 PM
const APPOINTMENT_DURATION = 60; // 60 minutes

// Function to convert time string to hour number
function timeToHour(timeStr) {
  if (timeStr.includes('T')) {
    // ISO format: "2025-07-14T15:00:00+01:00"
    return parseInt(timeStr.split('T')[1].split(':')[0]);
  } else if (timeStr.includes(':')) {
    // HH:MM format: "15:00"
    return parseInt(timeStr.split(':')[0]);
  }
  return parseInt(timeStr);
}

// Function to format hour as time string
function formatTime(hour) {
  return hour.toString().padStart(2, '0') + ':00';
}

// Extract busy hours from calendar events
const busyHours = [];
calendarEvents.forEach(event => {
  if (event.json && event.json.start && event.json.start.dateTime) {
    const startHour = timeToHour(event.json.start.dateTime);
    busyHours.push(startHour);
  }
});

// Create array of all business hours
const allBusinessHours = [];
for (let hour = BUSINESS_START; hour < BUSINESS_END; hour++) {
  allBusinessHours.push(hour);
}

// Calculate available hours (remove busy hours)
const availableHours = allBusinessHours.filter(hour => !busyHours.includes(hour));

// Function to check if requested time is available
function isRequestedTimeAvailable(requestedTime, availableHours) {
  if (requestedTime === 'any') {
    return availableHours.length > 0;
  }

  if (requestedTime === 'morning') {
    // Morning: 9 AM - 12 PM
    const morningHours = availableHours.filter(hour => hour >= 9 && hour < 12);
    return morningHours.length > 0;
  }

  if (requestedTime === 'afternoon') {
    // Afternoon: 12 PM - 5 PM
    const afternoonHours = availableHours.filter(hour => hour >= 12 && hour < 17);
    return afternoonHours.length > 0;
  }

  // Specific time (e.g., "15:00")
  const requestedHour = timeToHour(requestedTime);
  return availableHours.includes(requestedHour);
}

// Function to group consecutive hours into intervals
function groupConsecutiveHours(hours) {
  if (hours.length === 0) return [];

  const sorted = hours.sort((a, b) => a - b);
  const groups = [];
  let currentGroup = [sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] === sorted[i-1] + 1) {
      currentGroup.push(sorted[i]);
    } else {
      groups.push(currentGroup);
      currentGroup = [sorted[i]];
    }
  }
  groups.push(currentGroup);

  return groups;
}

// Function to format available hours as readable text
function formatAvailableSlots(availableHours) {
  if (availableHours.length === 0) {
    return "no available slots";
  }

  const groups = groupConsecutiveHours(availableHours);
  const formattedGroups = groups.map(group => {
    if (group.length === 1) {
      // Single hour
      return `${formatTime(group[0])} AM`.replace(/(\d{2}):00 AM/, (match, hour) => {
        const h = parseInt(hour);
        if (h === 12) return "12:00 PM";
        if (h > 12) return `${h-12}:00 PM`;
        if (h === 0) return "12:00 AM";
        return `${h}:00 AM`;
      });
    } else {
      // Range of hours
      const start = group[0];
      const end = group[group.length - 1];

      const formatHour = (hour) => {
        if (hour === 12) return "12:00 PM";
        if (hour > 12) return `${hour-12}:00 PM`;
        if (hour === 0) return "12:00 AM";
        return `${hour}:00 AM`;
      };

      return `from ${formatHour(start)} to ${formatHour(end)}`;
    }
  });

  if (formattedGroups.length === 1) {
    return formattedGroups[0];
  } else if (formattedGroups.length === 2) {
    return formattedGroups.join(' and ');
  } else {
    const lastGroup = formattedGroups.pop();
    return formattedGroups.join(', ') + ', and ' + lastGroup;
  }
}

// Function to get the target date from the requested time context
function getTargetDate() {
  // This should come from the Information Extractor output
  const extractorOutput = $('Information Extractor').first().json.output;
  if (extractorOutput.start_time) {
    return extractorOutput.start_time.split('T')[0];
  }
  return 'the requested date';
}

// Function to create ISO datetime string
function createISODateTime(requestedTime, baseDateTimeISO) {
  const baseDate = baseDateTimeISO.split('T')[0]; // Extract date part
  const timezone = baseDateTimeISO.substring(baseDateTimeISO.lastIndexOf('+')); // Extract timezone
  return `${baseDate}T${requestedTime}:00${timezone}`;
}

// Function to add hours to ISO datetime string
function addHoursToISODateTime(isoDateTime, hours) {
  const [datePart, timePart] = isoDateTime.split('T');
  const [timeOnly, timezone] = timePart.split('+');
  const [hour, minute, second] = timeOnly.split(':');

  const newHour = parseInt(hour) + hours;
  const formattedHour = newHour.toString().padStart(2, '0');

  return `${datePart}T${formattedHour}:${minute}:${second}+${timezone}`;
}

// Main logic
const isAvailable = isRequestedTimeAvailable(requestedTime, availableHours);
const targetDate = getTargetDate();

let response;

if (isAvailable) {
  // Get the base start_time for date and timezone
  const baseStartTime = $('Information Extractor').first().json.output.start_time;

  // Create start time in ISO format
  const startTime = createISODateTime(requestedTime, baseStartTime);

  // Create end time (1 hour later)
  const endTime = addHoursToISODateTime(startTime, 1);

  response = {
    available: true,
    message: `Yes, ${requestedTime === 'any' ? 'appointments are' : requestedTime + ' is'} available.`,
    start_time: startTime,
    end_time: endTime
  };
} else {
  const availableSlots = formatAvailableSlots(availableHours);

  // Format the date nicely (without year)
  const formatDate = (dateStr) => {
    const date = new Date(dateStr + 'T00:00:00');
    const options = { weekday: 'long', month: 'long', day: 'numeric' };
    return date.toLocaleDateString('en-US', options);
  };

  const formattedDate = formatDate(targetDate);

  response = {
    available: false,
    message: `For ${formattedDate}, we have ${availableSlots} available.`
  };
}

// Return the response
return [response];

